import React,{useState}from"react";import{Link}from"react-router-dom";import{sendPasswordReset}from"../../services/authService";import{AuthLayout}from"./Login";
export default function ForgotPassword(){const[email,setEmail]=useState("");const[msg,setMsg]=useState("");async function submit(e){e.preventDefault();try{await sendPasswordReset(email);setMsg("Password reset instructions were sent.");}catch(err){setMsg(err.message||"Unable to send reset email.")}}return <AuthLayout title="Forgot password" subtitle="Enter your registered email address."><form onSubmit={submit}><label>Email<input type="email" required value={email} onChange={e=>setEmail(e.target.value)}/></label>{msg&&<div className="success">{msg}</div>}<button>Send Reset Link</button><div className="links"><Link to="/login">Back to login</Link></div></form></AuthLayout>}
