import React,{useCallback,useEffect,useMemo,useState}from"react";import{getQueue,subscribeToQueue}from"../../services/queueService";
export default function QueueDisplay(){const[rows,setRows]=useState([]);const[now,setNow]=useState(new Date());const load=useCallback(()=>getQueue().then(setRows).catch(console.error),[]);useEffect(()=>{load();const off=subscribeToQueue(load);const t=setInterval(()=>setNow(new Date()),1000);return()=>{off();clearInterval(t)}},[load]);const lanes=useMemo(()=>{const m={};rows.forEach(r=>{const k=r.veterinarian?.full_name||"Veterinarian";(m[k]??=[]).push(r)});return m},[rows]);return <div className="display"><header><h1>Cruz Veterinary Clinic</h1><p>{now.toLocaleDateString()} · {now.toLocaleTimeString()}</p></header><div className="lanes">{Object.entries(lanes).map(([doctor,list])=>{const serving=list.find(r=>r.status==="Serving");const waiting=list.filter(r=>r.status==="Waiting");return <section key={doctor}><h2>{doctor}</h2><p>NOW SERVING</p><strong>{serving?.queue_number||"---"}</strong><h3>{serving?.pet?.pet_name||"Waiting for next patient"}</h3><div className="next"><b>NEXT</b>{waiting.slice(0,5).map(r=><span key={r.id}>{r.queue_number} · {r.pet?.pet_name||"Pet"}</span>)}</div></section>})}{Object.keys(lanes).length===0&&<div className="empty">No active queue at the moment.</div>}</div><style>{`*{box-sizing:border-box}body{margin:0}.display{min-height:100vh;background:#eaf8fd;padding:28px;font-family:Arial;color:#20313b}.display header{text-align:center}.display h1{color:#318fbe;font-size:36px;margin-bottom:5px}.lanes{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:24px;max-width:1100px;margin:30px auto}.lanes section,.empty{background:#fff;border-radius:24px;padding:30px;text-align:center;box-shadow:0 10px 30px #c9e4ef}.lanes section>strong{font-size:64px;color:#4DA8DA}.next{display:grid;gap:8px;margin-top:24px}.next span{background:#f0f9fc;padding:10px;border-radius:10px}.empty{grid-column:1/-1}`}</style></div>}
