import React,{useState}from"react";import{Link}from"react-router-dom";import{updatePassword}from"../../services/authService";import{AuthLayout}from"./Login";import PasswordInput from "../../components/PasswordInput";
export default function ResetPassword(){const[password,setPassword]=useState("");const[confirm,setConfirm]=useState("");const[msg,setMsg]=useState("");async function submit(e){e.preventDefault();if(password!==confirm)return setMsg("Passwords do not match.");try{await updatePassword(password);setMsg("Password updated successfully.");}catch(err){setMsg(err.message||"Unable to update password.")}}return <AuthLayout title="Set a new password" subtitle="Choose a secure password for your account."><form onSubmit={submit}><label>New Password<PasswordInput minLength="6" required value={password} onChange={e=>setPassword(e.target.value)}/></label><label>Confirm Password<PasswordInput minLength="6" required value={confirm} onChange={e=>setConfirm(e.target.value)}/></label>{msg&&<div className="success">{msg}</div>}<button>Update Password</button><div className="links"><Link to="/login">Go to login</Link></div></form></AuthLayout>}
